// Authoritative localhost storage, with a browser backup and revision conflicts surfaced.
window.SharedState=(()=>{
 let revision=0,ready=false,dirty=false,saving=false,lastState='',status='Connecting';
 const snapshot=()=>({visits,logs,headSettings,incidents});
 function badgeStatus(text){status=text;document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=text)}
 function cache(){localStorage.setItem(key,JSON.stringify(visits));localStorage.setItem(logKey,JSON.stringify(logs));localStorage.setItem(headStore,JSON.stringify(headSettings));localStorage.setItem(incidentKey,JSON.stringify(incidents))}
 function adopt(packet){if(!packet.state)return;const data=packet.state;visits=data.visits;logs=data.logs;headSettings=data.headSettings;incidents=data.incidents;revision=packet.revision;cache();lastState=JSON.stringify(data)}
 async function flush(){if(!ready||saving||!dirty)return;saving=true;dirty=false;const payload=snapshot();try{const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,state:payload})});const packet=await r.json();if(r.status===409){localStorage.setItem('amrita-conflict-backup',JSON.stringify(payload));dirty=false;adopt(packet);render();toast('Another portal updated the records first. Latest data loaded; your unsaved snapshot was backed up. Repeat your action after reviewing.')}else if(!r.ok)throw Error(packet.error);else{revision=packet.revision;lastState=JSON.stringify(payload);badgeStatus('Connected · SQLite revision '+revision)}}catch{dirty=true;badgeStatus('Offline · changes pending sync')}finally{saving=false;if(dirty&&status.startsWith('Connected'))flush()}}
 function enqueue(){dirty=true;if(ready)flush()}
 async function start(){try{const r=await fetch('/api/state');if(!r.ok)throw Error();const packet=await r.json();localStorage.setItem('amrita-before-server-import',JSON.stringify(snapshot()));if(packet.state)adopt(packet);else{revision=0;dirty=true}ready=true;badgeStatus('Connected · SQLite revision '+revision);if(dirty)await flush()}catch{badgeStatus('Offline · browser backup only')}render();setInterval(poll,5000)}
 async function poll(){if(saving)return;if(dirty){if(!ready){try{const r=await fetch('/api/state'),p=await r.json();revision=p.revision;ready=true;if(p.state&&lastState===''){localStorage.setItem('amrita-conflict-backup',JSON.stringify(snapshot()));adopt(p);dirty=false;toast('Shared records restored. Review your browser backup before repeating offline changes.');render()}}catch{return}}badgeStatus('Connected · synchronizing');return flush()}try{const r=await fetch('/api/state');if(!r.ok)throw Error();const p=await r.json();ready=true;if(p.revision!==revision){adopt(p);const el=document.activeElement;const editing=el&&['INPUT','TEXTAREA','SELECT'].includes(el.tagName);if(!editing&&!document.querySelector('dialog[open]'))render();else toast('Shared records updated. Refresh this portal after finishing your input.')}badgeStatus('Connected · SQLite revision '+revision)}catch{badgeStatus('Offline · browser backup only')}}
 return{start,enqueue,status:()=>status};
})();
